css:
.package .requireme input { flex: 1 1 auto; min-width: 0; }
.package .requireme .morse-copy { flex: 0 0 auto; font: inherit; font-size: 13px; color: currentColor; background: #fff; border: 1px solid #ccc; border-radius: 4px; padding: 4px 10px; cursor: pointer; }
.package .requireme .morse-copy:hover { background: #eee; }

js:
morse.watch(".package .requireme", el => {
  if (el.querySelector(".morse-copy")) return;
  const input = el.querySelector("input");
  if (!input) return;
  const btn = morse.el("button", {
    type: "button",
    class: "morse-copy",
    text: "Copy",
    on: {
      click: () => {
        navigator.clipboard.writeText(input.value)
          .then(() => morse.toast("Command copied"))
          .catch(() => { input.select(); morse.toast("Copy failed, press Ctrl+C"); });
      }
    }
  });
  el.appendChild(btn);
});
